Section HC4.
Variable x25519: list byte -> list byte -> list byte.
Variable aead_enc: list byte -> Z -> list byte -> list byte -> list byte.
Variable aead_dec: list byte -> Z -> list byte -> list byte -> option (list byte).
Variable xaead_enc: list byte -> list byte -> list byte -> list byte -> list byte.
Variable xaead_dec: list byte -> list byte -> list byte -> list byte -> option (list byte).
Variable CSw: compspecs.

(* what the common.h functions call: the environment (with nondet_size), the lower pieces' interfaces, protocol4 *)
Definition hc4_imports (cs: compspecs) : funspecs :=
  WgNoise.proof.protocol.prot_prog3.env_specs_ns CSw ++
  [@memcpy_spec cs; @memset_spec cs; @memcmp_spec cs; @calloc_spec CSw;
   @memzero_explicit_spec cs; @crypto_memneq_spec cs;
   @curve25519_generic_spec_of cs x25519;
   @chacha20poly1305_encrypt_spec_of cs aead_enc; @chacha20poly1305_decrypt_spec_of3 cs aead_dec;
   @xchacha20poly1305_encrypt_spec_of cs xaead_enc; @xchacha20poly1305_decrypt_spec_of3 cs xaead_dec] ++
  blake2s_G3 ++ prot_G4 x25519 aead_enc aead_dec xaead_enc xaead_dec CSw ++ [nondet_size_spec].

(* the v4 specifications (hc4_specs.v), in front of hc_specs3.v's *)
Definition hc4_new : funspecs :=
  [setup_device4_spec x25519; draw_real_clock4_spec; hs_take4_spec; hs_same4_spec CSw; hs_zeroed_from4_spec CSw;
   hs_same_but_next4_spec CSw; hs_randomize4_spec; pr_take4_spec; pr_same_but_cookie4_spec CSw; pr_same4_spec CSw;
   peer_randomize_rest4_spec; draw_peer_refs4_spec; dev_take4_spec; dev_same4_spec CSw; shim_take4_spec;
   shim_same4_spec; shim_no_warning4_spec; skb_take4_spec; skb_same4_spec CSw; replay_counter_fresh4_spec;
   hnodes_add4_spec x25519 CSw; hnodes_snap4_spec CSw; hnodes_same_except4_spec CSw; hnodes_free4_spec CSw;
   hnodes_pick4_spec CSw; kents_add4_spec CSw; kents_snap4_spec CSw; kent_same_but_next4_spec CSw;
   kents_same4_spec CSw; kents_same_but_next4_spec CSw; kents_hashed4_spec CSw; kents_free4_spec CSw;
   le32_load4_spec].

Definition hc4_G_all (bp cons iden: ident) : funspecs :=
  hc4_new ++ hc_G3_all x25519 aead_enc aead_dec bp cons iden.

Definition hc4_G_config_any := hc_select hc4_ids_config_any
  (hc4_G_all WgNoise.harness.x_config_any.code._x_config_any__M_BASEPOINT xH xH).
Definition hc4_G_consume_initiation_any := hc_select hc4_ids_consume_initiation_any
  (hc4_G_all WgNoise.harness.x_consume_initiation_any.code._x_consume_initiation_any__M_BASEPOINT WgNoise.harness.x_consume_initiation_any.code._x_consume_initiation_any__M_CONSTRUCTION WgNoise.harness.x_consume_initiation_any.code._x_consume_initiation_any__M_IDENTIFIER).
Definition hc4_G_consume_response_any := hc_select hc4_ids_consume_response_any
  (hc4_G_all WgNoise.harness.x_consume_response_any.code._x_consume_response_any__M_BASEPOINT xH xH).
Definition hc4_G_cookie_mac := hc_select hc4_ids_cookie_mac
