Definition hc4_G_cookie_reply := hc_select hc4_ids_cookie_reply
  (hc4_G_all WgNoise.harness.x_cookie_reply.code._x_cookie_reply__M_BASEPOINT xH xH).
Definition hc4_G_create_any := hc_select hc4_ids_create_any
  (hc4_G_all WgNoise.harness.x_create_any.code._x_create_any__M_BASEPOINT WgNoise.harness.x_create_any.code._x_create_any__M_CONSTRUCTION WgNoise.harness.x_create_any.code._x_create_any__M_IDENTIFIER).
Definition hc4_G_handshake_clear := hc_select hc4_ids_handshake_clear
  (hc4_G_all xH xH xH).
Definition hc4_G_handshake_receive := hc_select hc4_ids_handshake_receive
  (hc4_G_all WgNoise.harness.x_handshake_receive.code._x_handshake_receive__M_BASEPOINT WgNoise.harness.x_handshake_receive.code._x_handshake_receive__M_CONSTRUCTION WgNoise.harness.x_handshake_receive.code._x_handshake_receive__M_IDENTIFIER).
Definition hc4_G_keypairs := hc_select hc4_ids_keypairs
  (hc4_G_all WgNoise.harness.x_keypairs.code._x_keypairs__M_BASEPOINT xH xH).

(* every common.h function of each unit has its specification *)
Lemma hc4_ids_ok_config_any : map fst hc4_G_config_any = hc4_ids_config_any.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_consume_initiation_any : map fst hc4_G_consume_initiation_any = hc4_ids_consume_initiation_any.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_consume_response_any : map fst hc4_G_consume_response_any = hc4_ids_consume_response_any.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_cookie_mac : map fst hc4_G_cookie_mac = hc4_ids_cookie_mac.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_cookie_reply : map fst hc4_G_cookie_reply = hc4_ids_cookie_reply.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_create_any : map fst hc4_G_create_any = hc4_ids_create_any.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_handshake_clear : map fst hc4_G_handshake_clear = hc4_ids_handshake_clear.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_handshake_receive : map fst hc4_G_handshake_receive = hc4_ids_handshake_receive.
Proof. reflexivity. Qed.
Lemma hc4_ids_ok_keypairs : map fst hc4_G_keypairs = hc4_ids_keypairs.
Proof. reflexivity. Qed.

End HC4.

